-- =====================================================================
-- 009 · Niveles 4 a 8 (Episodios 4–8 del instituto)
--   - 38 temas nuevos en pensum_temas (Mis temas / dominio)
--   - Unidades 16 y 17 (Libro 2) para el Nivel 8
--   - Una lección por tema + banco-ep4…ep8 (4 patas) + examen-ep4…ep8 (reservado)
--   - 722 ejercicios: 304 estudio, 76 input, 114 output,
--     114 fluidez + 114 reservados para exámenes
-- Contenido propio (English My Way solo como guía del orden y los temas).
-- Pega TODO este archivo en Supabase → SQL Editor → Run.
-- Se puede correr varias veces sin dañar nada. Requiere 006, 007 y 008.
-- =====================================================================

-- ============ UNIDADES DEL LIBRO 2 (Nivel 8) ============
on conflict (materia_id, numero) do update set episodio = excluded.episodio,
  objetivo = coalesce(nullif(unidades.objetivo, ''), excluded.objetivo);

-- ============ TEMAS ============
on conflict (id) do update set episodio = excluded.episodio, orden = excluded.orden, nombre_es = excluded.nombre_es,
  nombre_en = excluded.nombre_en, descripcion = excluded.descripcion;

-- ============ LECCIONES Y BANCOS ============
on conflict (id) do update set unidad_id = excluded.unidad_id, episodio = excluded.episodio, orden = excluded.orden,
  tipo = excluded.tipo, titulo = excluded.titulo, descripcion = excluded.descripcion;

-- ============ EJERCICIOS ============
on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo, datos = excluded.datos,
  tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;
on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo, datos = excluded.datos,
  tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;
