insert into pensum_temas (id, episodio, orden, nombre_es, nombre_en, descripcion) values
  ('ep4-pasado-regular', 4, 1, 'Pasado simple: verbos regulares', 'Past simple (-ed)', 'Acciones terminadas: worked, played, studied, stopped. Igual para todas las personas.'),
  ('ep4-was-were', 4, 2, 'Was y were', 'was / were', 'El pasado de to be: I/he/she/it was; you/we/they were. Negativa wasn''t/weren''t.'),
  ('ep4-did', 4, 3, 'Did: preguntas y negativas en pasado', 'did / didn''t', 'Did + sujeto + verbo base? / didn''t + verbo base. Después de did el verbo NO va en pasado.'),
  ('ep4-used-to', 4, 4, 'Used to, be used to, get used to', 'used to', 'used to = solía (ya no); be used to + -ing = estar acostumbrado; get used to + -ing = acostumbrarse.'),
  ('ep4-pasado-irregular', 4, 5, 'Pasado simple: verbos irregulares', 'Irregular past', 'Verbos que cambian: go→went, have→had, see→saw, buy→bought, take→took, make→made, say→said.'),
  ('ep4-pasado-progresivo', 4, 6, 'Pasado progresivo', 'was / were + -ing', 'Lo que estaba pasando en un momento del pasado: I was working when she called; while = mientras.'),
  ('ep4-speak-talk', 4, 7, 'Speak y talk', 'speak vs talk', 'speak: idiomas, hablar formal o en público (speak English). talk: conversar con alguien (talk to/with someone).'),
  ('ep4-dias', 4, 8, 'Días y expresiones de tiempo en pasado', 'Days & time expressions', 'Monday…Sunday, on Monday, yesterday, last week/month/year, two days ago, this morning.'),
  ('ep5-both-either-neither', 5, 1, 'Both, either y neither', 'both / either / neither', 'both = los dos; either = cualquiera de los dos; neither = ninguno de los dos. Me neither / Neither do I.'),
  ('ep5-neither-nor', 5, 2, 'Neither…nor y either…or', 'neither…nor / either…or', 'either A or B = o A o B; neither A nor B = ni A ni B (el verbo va en afirmativo).'),
  ('ep5-negativas', 5, 3, 'Palabras negativas', 'nobody, nothing, nowhere, none, never', 'nobody/no one = nadie; nothing = nada; nowhere = ninguna parte; none = ninguno; never = nunca. Una sola negación por frase.'),
  ('ep5-pronombres-objeto', 5, 4, 'Pronombres objeto', 'me, you, him, her, it, us, them', 'Van después del verbo o de una preposición: call me, help him, with them, for us.'),
  ('ep5-oficina', 5, 5, 'La oficina y el computador', 'Office & computer', 'desk, chair, printer, screen, keyboard, mouse, file, folder, meeting, email, to print, to save.'),
  ('ep5-there-is', 5, 6, 'There is / there are', 'there is / there are', 'Hay: there is + singular, there are + plural; Is there…? Are there…? There isn''t / there aren''t.'),
  ('ep5-how', 5, 7, 'Preguntas con how', 'how much / how many / how long / how old', 'How much (cantidad incontable o precio), how many (contable), how long (duración), how old (edad), how about (¿qué tal…?).'),
  ('ep5-have-got', 5, 8, 'Have got', 'have got / has got', 'have got = have (tener), muy usado en inglés británico: I''ve got, she''s got, Have you got…?'),
  ('ep6-contables', 6, 1, 'Contables e incontables', 'Countable / uncountable', 'Contables: an apple, two apples. Incontables (sin plural ni a): water, rice, money, information, bread.'),
  ('ep6-some-any', 6, 2, 'Some y any', 'some / any', 'some en afirmativas y ofrecimientos (Would you like some…?); any en negativas y preguntas.'),
  ('ep6-cuantificadores', 6, 3, 'Much, many, a lot of, few, little', 'Quantifiers', 'many/few (contables), much/little (incontables), a lot of (los dos). a few / a little = un poco; few / little = casi nada.'),
  ('ep6-too-enough', 6, 4, 'Too y enough', 'too / enough', 'too + adjetivo = demasiado (too expensive); adjetivo + enough = suficientemente (big enough); enough + sustantivo (enough money).'),
  ('ep6-comida', 6, 5, 'Comida y restaurante', 'Food & restaurant', 'Pedir y reservar: I''d like to book a table, menu, bill, tip; carnes, verduras, cubiertos, formas de cocinar.'),
  ('ep6-meses-fechas', 6, 6, 'Meses, fechas y ordinales', 'Months, dates & ordinals', 'January…December; first, second, third, twenty-first; in May, on May 5th; fracciones: a half, a quarter, two thirds.'),
  ('ep6-frecuencia', 6, 7, 'Adverbios de frecuencia', 'always, usually, often, sometimes, never', 'Van antes del verbo principal (I always study) y después de to be (I''m always late): always, usually, often, sometimes, seldom, hardly ever, never.'),
  ('ep6-something', 6, 8, 'Something, anyone, somewhere…', 'some-/any- words', 'something/anything (algo), someone/anyone (alguien), somewhere/anywhere (algún lugar). some- en afirmativas; any- en preguntas y negativas.'),
  ('ep7-preposiciones', 7, 1, 'Preposiciones de tiempo y lugar', 'in, on, at, to, from, by, with, for', 'at (hora, lugar exacto), on (días, fechas, calles), in (meses, años, ciudades); from… to…, by car, with someone, for (para).'),
  ('ep7-posesivo-s', 7, 2, 'Posesión con ''s', 'Possessive ''s / s''', 'El dueño + ''s: Maria''s phone; plural con s: the students'' books; plural irregular: the children''s toys.'),
  ('ep7-bebidas', 7, 3, 'Bebidas y en el bar', 'Drinks & at the bar', 'coffee, tea with lemon, hot chocolate, juice, milkshake, soda, beer, wine; pedir: I''ll have…, Can I get…?; all right.'),
  ('ep7-pronombres-posesivos', 7, 4, 'Adjetivos y pronombres posesivos', 'my/mine, your/yours, our/ours…', 'Adjetivo + sustantivo: my car. Pronombre solo: It''s mine. mine, yours, his, hers, ours, theirs (sin ''s).'),
  ('ep7-adverbios', 7, 5, 'Adverbios de modo', 'Adverbs (-ly, fast, hard, well)', 'Cómo se hace algo: adjetivo + -ly (slow → slowly); irregulares: good → well, fast, hard, late. Ojo: friendly y elderly son adjetivos.'),
  ('ep7-tag-questions', 7, 6, 'Tag questions', '…, isn''t it? / …, don''t you?', 'Preguntas cortas al final para confirmar: afirmativa → tag negativa (You''re tired, aren''t you?); negativa → tag afirmativa (He can''t drive, can he?).'),
  ('ep7-preguntas-negativas', 7, 7, 'Negaciones y preguntas negativas', 'Negatives & negative questions', 'Contracciones con not (isn''t, don''t, can''t, didn''t); preguntas negativas para sorpresa o confirmación: Didn''t she call? Don''t you like it?'),
  ('ep8-will', 8, 1, 'Futuro con will', 'will / won''t', 'Decisiones del momento, promesas y predicciones: I''ll help you, It will rain, I won''t tell anybody. will + verbo base.'),
  ('ep8-going-to', 8, 2, 'Futuro con going to', 'be going to', 'Planes ya decididos e indicios claros: We''re going to eat sushi tonight; Look at the clouds, it''s going to rain.'),
  ('ep8-shall', 8, 3, 'Shall para ofrecer y sugerir', 'Shall I…? / Shall we…?', 'Shall I…? = ¿Quieres que yo…? (ofrecer). Shall we…? = ¿Qué tal si…? (sugerir). Se usa con I y we.'),
  ('ep8-carro', 8, 4, 'El carro y alquilar un carro', 'Cars & renting a car', 'rent a car, driver''s license, credit card, mileage, automatic / standard shift, gas, tire, mechanic, insurance.'),
  ('ep8-presente-perfecto', 8, 5, 'Presente perfecto', 'have / has + participle', 'Experiencias y cosas sin tiempo exacto: I have visited Medellín; She has never seen snow; Have you ever…? have/has + participio.'),
  ('ep8-just-already-yet', 8, 6, 'Just, already y yet', 'just / already / yet', 'just = acabo de (I''ve just eaten); already = ya (She has already left); yet = todavía / ya (en negativas y preguntas, al final).'),
  ('ep8-ropa', 8, 7, 'La ropa', 'Clothes', 'shirt, T-shirt, jeans, pants, dress, skirt, jacket, coat, raincoat, suit, tie, scarf, socks, shoes, hat; wear, put on, take off, try on.')
