  ('ep4-dias', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 8), 4, 8, 'tema', 'Días de la semana y cuándo pasó', 'Decir cuándo pasó algo: on Monday, last week, two days ago (Unidad 8).'),
