  ('ep5-both-either-neither', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 9), 5, 1, 'tema', 'Both, either, neither', 'Hablar de dos cosas o personas a la vez (Unidad 9).'),
  ('ep5-neither-nor', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 9), 5, 2, 'tema', 'Ni… ni… / o… o…', 'Unir dos opciones: either…or, neither…nor (Unidad 9).'),
  ('ep5-negativas', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 9), 5, 3, 'tema', 'Nadie, nada, nunca', 'Palabras negativas sin la doble negación del español (Unidad 9).'),
  ('ep5-pronombres-objeto', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 9), 5, 4, 'tema', 'Me, him, her, them…', 'Los pronombres que reciben la acción (Unidad 9).'),
  ('ep5-oficina', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 9), 5, 5, 'tema', 'En la oficina', 'Vocabulario de oficina y computador (Unidad 9).'),
  ('ep5-there-is', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 10), 5, 6, 'tema', 'There is, there are: hay', 'Decir qué hay en un lugar (Unidad 10).'),
  ('ep5-how', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 10), 5, 7, 'tema', 'How much, how many, how long', 'Las preguntas con how del repaso (Unidad 10).'),
