  ('ep6-contables', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 11), 6, 1, 'tema', 'Contables e incontables', 'Qué se puede contar y qué no (Unidad 11).'),
  ('ep6-some-any', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 11), 6, 2, 'tema', 'Some y any', 'Algo de, nada de, ¿hay…? (Unidad 11).'),
  ('ep6-cuantificadores', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 11), 6, 3, 'tema', '¿Cuánto hay? Cuantificadores', 'Mucho, poco y bastante con contables e incontables (Unidad 11).'),
  ('ep6-too-enough', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 11), 6, 4, 'tema', 'Demasiado y suficiente', 'Too y enough para quejarse o pedir en el restaurante (Unidad 11).'),
  ('ep6-comida', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 11), 6, 5, 'tema', 'En el restaurante', 'Reservar, pedir y pagar en un restaurante (Unidad 11).'),
  ('ep6-meses-fechas', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 12), 6, 6, 'tema', 'Meses, fechas y números ordinales', 'Decir fechas y cumpleaños (Unidad 12).'),
  ('ep6-frecuencia', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 12), 6, 7, 'tema', 'Siempre, a veces, nunca', 'Qué tan seguido haces las cosas y dónde va el adverbio (Unidad 12).'),
  ('ep6-something', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 12), 6, 8, 'tema', 'Algo, alguien, algún lugar', 'Las palabras con some- y any- (Unidad 12).'),
  ('banco-ep7', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 13), 7, 90, 'banco', 'Banco de práctica · Episodio 7', 'Ejercicios de las 4 patas para Mi camino.'),
  ('examen-ep7', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 13), 7, 99, 'examen', 'Banco reservado · Episodio 7', 'Solo para exámenes.'),
  ('ep7-preposiciones', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 13), 7, 1, 'tema', 'Preposiciones: in, on, at y más', 'Las preposiciones más usadas, como en el bar (Unidad 13).'),
  ('ep7-posesivo-s', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 13), 7, 2, 'tema', 'El ''s de posesión', 'Decir de quién es algo con ''s (Unidad 13).'),
  ('ep7-bebidas', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 13), 7, 3, 'tema', 'En el bar: pedir bebidas', 'Pedir y ofrecer bebidas, y usar all right (Unidad 13).'),
  ('ep7-pronombres-posesivos', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 14), 7, 4, 'tema', 'My o mine: posesivos', 'Decir que algo es mío, tuyo, nuestro (Unidad 14).'),
  ('ep7-adverbios', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 14), 7, 5, 'tema', 'Adverbios: cómo haces las cosas', 'Formar adverbios con -ly y los irregulares (Unidad 14).'),
  ('ep7-tag-questions', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 15), 7, 6, 'tema', 'Tag questions: ¿verdad?', 'Confirmar con ¿cierto? / ¿verdad? al final (Unidad 15).'),
  ('ep7-preguntas-negativas', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 15), 7, 7, 'tema', 'Repaso: negaciones y preguntas negativas', 'Cierre del Libro 1: negar bien y preguntar en negativo (Unidad 15).'),
  ('banco-ep8', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 16), 8, 90, 'banco', 'Banco de práctica · Episodio 8', 'Ejercicios de las 4 patas para Mi camino.'),
  ('examen-ep8', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 16), 8, 99, 'examen', 'Banco reservado · Episodio 8', 'Solo para exámenes.'),
  ('ep8-will', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 16), 8, 1, 'tema', 'Will: el futuro simple', 'Prometer, decidir en el momento y predecir (Unidad 16).'),
  ('ep8-going-to', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 16), 8, 2, 'tema', 'Going to: planes', 'Hablar de planes y de lo que es evidente que va a pasar (Unidad 16).'),
  ('ep8-shall', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 16), 8, 3, 'tema', 'Shall I…? Shall we…?', 'Ofrecer ayuda y sugerir planes con cortesía (Unidad 16).'),
  ('ep8-carro', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 16), 8, 4, 'tema', 'Alquilar un carro', 'Vocabulario para alquilar y manejar un carro (Unidad 16).'),
  ('ep8-presente-perfecto', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 17), 8, 5, 'tema', 'Presente perfecto: he hecho', 'Experiencias de vida y recuerdos (Unidad 17).'),
  ('ep8-just-already-yet', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 17), 8, 6, 'tema', 'Just, already, yet', 'Acabo de, ya, todavía no (Unidad 17).'),
  ('ep8-ropa', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 17), 8, 7, 'tema', 'La ropa', 'Vocabulario de ropa y verbos para vestirse (Unidad 17).')
insert into ejercicios (id, leccion_id, orden, tipo, datos, tema_id, pata, reservado) values
  ('ep4-pasado-regular-01', 'ep4-pasado-regular', 1, 'elegir', '{"frase": "Yesterday I ___ ten pairs of shoes.", "opciones": ["sold", "sells", "sell"], "correcta": 0, "es": "Ayer vendí diez pares de zapatos.", "explicacion": "sell es irregular: sold. Ojo: no todos llevan -ed."}'::jsonb, 'ep4-pasado-regular', 'estudio', false),
  ('ep4-pasado-regular-02', 'ep4-pasado-regular', 2, 'elegir', '{"frase": "Last night we ___ a movie at home.", "opciones": ["watch", "watching", "watched"], "correcta": 2, "es": "Anoche vimos una película en casa.", "explicacion": "watch → watched. En pasado no cambia con we, he, they."}'::jsonb, 'ep4-pasado-regular', 'estudio', false),
  ('ep4-pasado-regular-03', 'ep4-pasado-regular', 3, 'elegir', '{"frase": "She ___ English for two hours yesterday.", "opciones": ["studyed", "studied", "studies"], "correcta": 1, "es": "Ella estudió inglés dos horas ayer.", "explicacion": "Consonante + y → ied: study → studied."}'::jsonb, 'ep4-pasado-regular', 'estudio', false),
  ('ep4-pasado-regular-04', 'ep4-pasado-regular', 4, 'elegir', '{"frase": "The bus ___ in front of the hotel.", "opciones": ["stoped", "stops", "stopped"], "correcta": 2, "es": "El bus paró frente al hotel.", "explicacion": "Verbo corto que termina en consonante-vocal-consonante: se dobla la letra: stop → stopped."}'::jsonb, 'ep4-pasado-regular', 'estudio', false),
  ('ep4-pasado-regular-05', 'ep4-pasado-regular', 5, 'escribir', '{"respuestas": ["i worked in my store on saturday", "i worked in my shop on saturday", "i worked at my store on saturday"], "mostrar": "I worked in my store on Saturday.", "es": "Trabajé en mi tienda el sábado.", "explicacion": "work → worked."}'::jsonb, 'ep4-pasado-regular', 'estudio', false),
  ('ep4-pasado-regular-06', 'ep4-pasado-regular', 6, 'ordenar', '{"frase": "We arrived at the hotel at nine", "es": "Llegamos al hotel a las nueve.", "explicacion": "Sujeto + verbo en pasado + lugar + hora."}'::jsonb, 'ep4-pasado-regular', 'estudio', false),
  ('ep4-pasado-regular-07', 'ep4-pasado-regular', 7, 'emparejar', '{"pares": [["work", "worked"], ["study", "studied"], ["stop", "stopped"], ["arrive", "arrived"]], "es": "", "explicacion": "Reglas del -ed: +ed, y→ied, doblar consonante, +d si termina en e."}'::jsonb, 'ep4-pasado-regular', 'estudio', false),
  ('ep4-pasado-regular-08', 'ep4-pasado-regular', 8, 'escuchar', '{"opciones": ["I call the hotel every day.", "I called the hotel yesterday.", "I called the doctor yesterday."], "correcta": 1, "audio": "I called the hotel yesterday.", "es": "Llamé al hotel ayer.", "explicacion": "La -ed de called suena como una d suave: /kɔːld/."}'::jsonb, 'ep4-pasado-regular', 'estudio', false),
  ('banco-ep4-pasado-regular-01', 'banco-ep4', 1, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Yesterday Maria opened the store at eight.", "es": "Ayer María abrió la tienda a las ocho."}, {"en": "She cleaned the shelves and answered messages.", "es": "Limpió los estantes y respondió mensajes."}, {"en": "In the afternoon, she delivered three orders.", "es": "En la tarde entregó tres pedidos."}], "pregunta": "What did Maria do in the afternoon?", "pregunta_es": "¿Qué hizo María en la tarde?", "opciones": ["She delivered three orders.", "She opened the store.", "She cleaned the shelves."], "correcta": 0, "explicacion": "\"delivered\" = entregó. Afternoon = tarde."}'::jsonb, 'ep4-pasado-regular', 'input', false),
  ('banco-ep4-pasado-regular-02', 'banco-ep4', 2, 'comprension', '{"modo": "leer", "lineas": [{"en": "Last weekend Carlos visited his parents in Pamplona.", "es": "El fin de semana pasado Carlos visitó a sus papás en Pamplona."}, {"en": "They cooked a big lunch and talked a lot.", "es": "Cocinaron un gran almuerzo y hablaron mucho."}, {"en": "Carlos returned to Cúcuta on Sunday night.", "es": "Carlos regresó a Cúcuta el domingo en la noche."}], "pregunta": "When did Carlos return?", "pregunta_es": "¿Cuándo regresó Carlos?", "opciones": ["On Saturday morning.", "On Sunday night.", "Last Monday."], "correcta": 1, "explicacion": "returned = regresó; on Sunday night = el domingo en la noche."}'::jsonb, 'ep4-pasado-regular', 'input', false),
  ('banco-ep4-pasado-regular-03', 'banco-ep4', 3, 'decir', '{"es": "Ayer trabajé mucho.", "respuestas": ["yesterday i worked a lot", "i worked a lot yesterday"], "mostrar": "Yesterday I worked a lot.", "explicacion": "work → worked."}'::jsonb, 'ep4-pasado-regular', 'output', false),
  ('banco-ep4-pasado-regular-04', 'banco-ep4', 4, 'decir', '{"es": "Ella me llamó anoche.", "respuestas": ["she called me last night"], "mostrar": "She called me last night.", "explicacion": "call → called; last night = anoche."}'::jsonb, 'ep4-pasado-regular', 'output', false),
