  ('examen-ep4-used-to-01', 'examen-ep4', 10, 'elegir', '{"frase": "My father ___ smoke, but he stopped.", "opciones": ["used to", "gets used to", "is used to"], "correcta": 0, "es": "Mi papá fumaba, pero dejó.", "explicacion": "Hábito pasado: used to."}'::jsonb, 'ep4-used-to', 'estudio', true),
  ('examen-ep4-used-to-02', 'examen-ep4', 11, 'elegir', '{"frase": "I can''t get used to ___ in this cold city.", "opciones": ["lived", "living", "live"], "correcta": 1, "es": "No me acostumbro a vivir en esta ciudad fría.", "explicacion": "get used to + -ing."}'::jsonb, 'ep4-used-to', 'estudio', true),
  ('examen-ep4-used-to-03', 'examen-ep4', 12, 'escribir', '{"respuestas": ["she wasnt used to walking so much", "she was not used to walking so much", "she wasnt used to walking a lot", "she was not used to walking a lot"], "mostrar": "She wasn''t used to walking so much.", "es": "Ella no estaba acostumbrada a caminar tanto.", "explicacion": "wasn''t used to + walking."}'::jsonb, 'ep4-used-to', 'estudio', true),
  ('ep4-pasado-irregular-01', 'ep4-pasado-irregular', 1, 'elegir', '{"frase": "Last year I ___ to Medellín.", "opciones": ["goed", "go", "went"], "correcta": 2, "es": "El año pasado fui a Medellín.", "explicacion": "go → went."}'::jsonb, 'ep4-pasado-irregular', 'estudio', false),
  ('ep4-pasado-irregular-02', 'ep4-pasado-irregular', 2, 'elegir', '{"frase": "We ___ dinner at a nice restaurant.", "opciones": ["haved", "have", "had"], "correcta": 2, "es": "Cenamos en un buen restaurante.", "explicacion": "have → had."}'::jsonb, 'ep4-pasado-irregular', 'estudio', false),
  ('ep4-pasado-irregular-03', 'ep4-pasado-irregular', 3, 'elegir', '{"frase": "She ___ a beautiful dress.", "opciones": ["buyed", "bought", "brought"], "correcta": 1, "es": "Compró un vestido hermoso.", "explicacion": "buy → bought (brought es de bring)."}'::jsonb, 'ep4-pasado-irregular', 'estudio', false),
  ('ep4-pasado-irregular-04', 'ep4-pasado-irregular', 4, 'elegir', '{"frase": "I ___ the train at 7 a.m.", "opciones": ["took", "take", "taked"], "correcta": 0, "es": "Tomé el tren a las 7 a. m.", "explicacion": "take → took."}'::jsonb, 'ep4-pasado-irregular', 'estudio', false),
  ('ep4-pasado-irregular-05', 'ep4-pasado-irregular', 5, 'escribir', '{"respuestas": ["i saw my brother yesterday", "yesterday i saw my brother"], "mostrar": "I saw my brother yesterday.", "es": "Vi a mi hermano ayer.", "explicacion": "see → saw."}'::jsonb, 'ep4-pasado-irregular', 'estudio', false),
  ('ep4-pasado-irregular-06', 'ep4-pasado-irregular', 6, 'ordenar', '{"frase": "My wife made a delicious cake last Sunday", "es": "Mi esposa hizo un pastel delicioso el domingo pasado.", "explicacion": "make → made."}'::jsonb, 'ep4-pasado-irregular', 'estudio', false),
  ('ep4-pasado-irregular-07', 'ep4-pasado-irregular', 7, 'emparejar', '{"pares": [["go", "went"], ["see", "saw"], ["buy", "bought"], ["think", "thought"]], "es": "", "explicacion": "Estos se aprenden de memoria."}'::jsonb, 'ep4-pasado-irregular', 'estudio', false),
  ('ep4-pasado-irregular-08', 'ep4-pasado-irregular', 8, 'escuchar', '{"opciones": ["He told me the truth.", "He sold me the truth.", "He tells me the truth."], "correcta": 0, "audio": "He told me the truth.", "es": "Me dijo la verdad.", "explicacion": "tell → told."}'::jsonb, 'ep4-pasado-irregular', 'estudio', false),
  ('banco-ep4-pasado-irregular-01', 'banco-ep4', 33, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Last Friday I went to the bank.", "es": "El viernes pasado fui al banco."}, {"en": "I paid the rent and got some money.", "es": "Pagué el arriendo y saqué algo de dinero."}, {"en": "Then I met a friend and we drank coffee.", "es": "Luego me encontré con un amigo y tomamos café."}], "pregunta": "What did he pay?", "pregunta_es": "¿Qué pagó?", "opciones": ["The coffee.", "The car.", "The rent."], "correcta": 2, "explicacion": "paid = pagó (pay → paid)."}'::jsonb, 'ep4-pasado-irregular', 'input', false),
  ('banco-ep4-pasado-irregular-02', 'banco-ep4', 34, 'comprension', '{"modo": "leer", "lineas": [{"en": "Lyle flew to London on Monday.", "es": "Lyle voló a Londres el lunes."}, {"en": "He took a taxi to the hotel and gave the driver a good tip.", "es": "Tomó un taxi al hotel y le dio buena propina al conductor."}, {"en": "He felt tired, so he slept for ten hours.", "es": "Se sentía cansado, así que durmió diez horas."}], "pregunta": "What did Lyle give the driver?", "pregunta_es": "¿Qué le dio Lyle al conductor?", "opciones": ["His passport.", "A suitcase.", "A good tip."], "correcta": 2, "explicacion": "gave = dio; tip = propina."}'::jsonb, 'ep4-pasado-irregular', 'input', false),
  ('banco-ep4-pasado-irregular-03', 'banco-ep4', 35, 'decir', '{"es": "Fui al supermercado.", "respuestas": ["i went to the supermarket"], "mostrar": "I went to the supermarket.", "explicacion": "go → went."}'::jsonb, 'ep4-pasado-irregular', 'output', false),
  ('banco-ep4-pasado-irregular-04', 'banco-ep4', 36, 'decir', '{"es": "Ella me dio un regalo.", "respuestas": ["she gave me a gift", "she gave me a present"], "mostrar": "She gave me a gift.", "explicacion": "give → gave."}'::jsonb, 'ep4-pasado-irregular', 'output', false),
  ('banco-ep4-pasado-irregular-05', 'banco-ep4', 37, 'libre', '{"pregunta": "Tell a story about your last trip in 4 sentences. Use at least four irregular verbs.", "pregunta_es": "Cuenta tu último viaje en 4 frases. Usa al menos cuatro verbos irregulares.", "ejemplo": "Last December I went to Cartagena with my family. We took a plane. We ate fish and drank juice. We saw the old city.", "criterio": "Verbos irregulares en pasado (went, took, ate, saw, had…); sin -ed en irregulares.", "explicacion": "Verbos irregulares en pasado (went, took, ate, saw, had…); sin -ed en irregulares."}'::jsonb, 'ep4-pasado-irregular', 'output', false),
  ('banco-ep4-pasado-irregular-06', 'banco-ep4', 38, 'rapido', '{"frase": "eat → ___", "opciones": ["eated", "ate"], "correcta": 1, "es": "comer → comió", "explicacion": "eat, ate, eaten.", "segundos": 6}'::jsonb, 'ep4-pasado-irregular', 'fluidez', false),
  ('banco-ep4-pasado-irregular-07', 'banco-ep4', 39, 'rapido', '{"frase": "write → ___", "opciones": ["writed", "wrote"], "correcta": 1, "es": "escribir → escribió", "explicacion": "write, wrote, written.", "segundos": 6}'::jsonb, 'ep4-pasado-irregular', 'fluidez', false),
  ('banco-ep4-pasado-irregular-08', 'banco-ep4', 40, 'rapido', '{"frase": "come → ___", "opciones": ["comed", "came"], "correcta": 1, "es": "venir → vino", "explicacion": "come, came, come.", "segundos": 6}'::jsonb, 'ep4-pasado-irregular', 'fluidez', false),
  ('examen-ep4-pasado-irregular-01', 'examen-ep4', 13, 'elegir', '{"frase": "They ___ a new car last month.", "opciones": ["buy", "buyed", "bought"], "correcta": 2, "es": "Compraron un carro nuevo el mes pasado.", "explicacion": "buy → bought."}'::jsonb, 'ep4-pasado-irregular', 'estudio', true),
  ('examen-ep4-pasado-irregular-02', 'examen-ep4', 14, 'elegir', '{"frase": "I ___ a strange noise last night.", "opciones": ["heard", "hear", "heared"], "correcta": 0, "es": "Oí un ruido raro anoche.", "explicacion": "hear → heard."}'::jsonb, 'ep4-pasado-irregular', 'estudio', true),
  ('examen-ep4-pasado-irregular-03', 'examen-ep4', 15, 'escribir', '{"respuestas": ["i wrote an email to the hotel", "i wrote the hotel an email"], "mostrar": "I wrote an email to the hotel.", "es": "Escribí un correo al hotel.", "explicacion": "write → wrote."}'::jsonb, 'ep4-pasado-irregular', 'estudio', true),
  ('ep4-pasado-progresivo-01', 'ep4-pasado-progresivo', 1, 'elegir', '{"frase": "I ___ dinner when the phone rang.", "opciones": ["made", "was making", "were making"], "correcta": 1, "es": "Estaba haciendo la cena cuando sonó el teléfono.", "explicacion": "Acción larga: was + -ing; la interrupción en pasado simple."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', false),
  ('ep4-pasado-progresivo-02', 'ep4-pasado-progresivo', 2, 'elegir', '{"frase": "They ___ TV at 9 p.m.", "opciones": ["watching", "was watching", "were watching"], "correcta": 2, "es": "Estaban viendo TV a las 9 p. m.", "explicacion": "They → were + -ing."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', false),
  ('ep4-pasado-progresivo-03', 'ep4-pasado-progresivo', 3, 'elegir', '{"frase": "While I was driving, my wife ___.", "opciones": ["was sleeping", "sleeps", "were sleeping"], "correcta": 0, "es": "Mientras yo manejaba, mi esposa dormía.", "explicacion": "While = dos acciones al mismo tiempo, ambas en progresivo."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', false),
  ('ep4-pasado-progresivo-04', 'ep4-pasado-progresivo', 4, 'elegir', '{"frase": "What ___ you doing yesterday at six?", "opciones": ["did", "were", "was"], "correcta": 1, "es": "¿Qué estabas haciendo ayer a las seis?", "explicacion": "Pregunta: What + were + you + -ing?"}'::jsonb, 'ep4-pasado-progresivo', 'estudio', false),
  ('ep4-pasado-progresivo-05', 'ep4-pasado-progresivo', 5, 'escribir', '{"respuestas": ["i was working when you arrived", "i was working when you came"], "mostrar": "I was working when you arrived.", "es": "Estaba trabajando cuando llegaste.", "explicacion": "was working + when + pasado simple."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', false),
  ('ep4-pasado-progresivo-06', 'ep4-pasado-progresivo', 6, 'ordenar', '{"frase": "It was raining when we left the hotel", "es": "Estaba lloviendo cuando salimos del hotel.", "explicacion": "was + -ing + when + pasado simple."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', false),
  ('ep4-pasado-progresivo-07', 'ep4-pasado-progresivo', 7, 'emparejar', '{"pares": [["I was working", "yo estaba trabajando"], ["they were sleeping", "ellos estaban durmiendo"], ["when", "cuando"], ["while", "mientras"]], "es": "", "explicacion": "El pasado progresivo usa was/were + verbo con -ing."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', false),
  ('ep4-pasado-progresivo-08', 'ep4-pasado-progresivo', 8, 'escuchar', '{"opciones": ["We had lunch when he called.", "We are having lunch when he calls.", "We were having lunch when he called."], "correcta": 2, "audio": "We were having lunch when he called.", "es": "Estábamos almorzando cuando llamó.", "explicacion": "were having = estábamos teniendo."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', false),
  ('banco-ep4-pasado-progresivo-01', 'banco-ep4', 41, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Kathryn was feeding her cat when the phone rang.", "es": "Kathryn estaba alimentando a su gato cuando sonó el teléfono."}, {"en": "It was Lyle. He was waiting at the airport.", "es": "Era Lyle. Estaba esperando en el aeropuerto."}, {"en": "While they were talking, the cat was eating.", "es": "Mientras hablaban, el gato estaba comiendo."}], "pregunta": "What was Kathryn doing when the phone rang?", "pregunta_es": "¿Qué estaba haciendo Kathryn cuando sonó el teléfono?", "opciones": ["She was feeding her cat.", "She was waiting at the airport.", "She was eating."], "correcta": 0, "explicacion": "was feeding = estaba alimentando."}'::jsonb, 'ep4-pasado-progresivo', 'input', false),
  ('banco-ep4-pasado-progresivo-02', 'banco-ep4', 42, 'comprension', '{"modo": "leer", "lineas": [{"en": "At 10 a.m. yesterday, the store was full.", "es": "Ayer a las 10 a. m. la tienda estaba llena."}, {"en": "Maria was helping a client, and Uwaldo was doing a live on TikTok.", "es": "María estaba atendiendo a una clienta y Uwaldo estaba haciendo un live en TikTok."}, {"en": "Suddenly, the lights went out.", "es": "De repente, se fue la luz."}], "pregunta": "What was Uwaldo doing?", "pregunta_es": "¿Qué estaba haciendo Uwaldo?", "opciones": ["He was doing a live on TikTok.", "He was sleeping.", "He was helping a client."], "correcta": 0, "explicacion": "was doing a live = estaba haciendo un live."}'::jsonb, 'ep4-pasado-progresivo', 'input', false),
  ('banco-ep4-pasado-progresivo-03', 'banco-ep4', 43, 'decir', '{"es": "Estaba estudiando a las ocho.", "respuestas": ["i was studying at eight", "i was studying at 8"], "mostrar": "I was studying at eight.", "explicacion": "was + studying."}'::jsonb, 'ep4-pasado-progresivo', 'output', false),
  ('banco-ep4-pasado-progresivo-04', 'banco-ep4', 44, 'decir', '{"es": "¿Qué estabas haciendo?", "respuestas": ["what were you doing"], "mostrar": "What were you doing?", "explicacion": "What + were + you + doing."}'::jsonb, 'ep4-pasado-progresivo', 'output', false),
  ('banco-ep4-pasado-progresivo-05', 'banco-ep4', 45, 'libre', '{"pregunta": "What were you and your family doing yesterday at 7 p.m.? Write three sentences.", "pregunta_es": "¿Qué estaban haciendo tú y tu familia ayer a las 7 p. m.? Escribe tres frases.", "ejemplo": "Yesterday at 7 p.m. I was answering messages. My wife was cooking. My daughter was playing with her dolls.", "criterio": "was/were + verbo -ing para acciones en progreso.", "explicacion": "was/were + verbo -ing para acciones en progreso."}'::jsonb, 'ep4-pasado-progresivo', 'output', false),
  ('banco-ep4-pasado-progresivo-06', 'banco-ep4', 46, 'rapido', '{"frase": "She ___ sleeping.", "opciones": ["were", "was"], "correcta": 1, "es": "Estaba durmiendo.", "explicacion": "She → was.", "segundos": 6}'::jsonb, 'ep4-pasado-progresivo', 'fluidez', false),
  ('banco-ep4-pasado-progresivo-07', 'banco-ep4', 47, 'rapido', '{"frase": "We were ___.", "opciones": ["working", "work"], "correcta": 0, "es": "Estábamos trabajando.", "explicacion": "were + -ing.", "segundos": 6}'::jsonb, 'ep4-pasado-progresivo', 'fluidez', false),
  ('banco-ep4-pasado-progresivo-08', 'banco-ep4', 48, 'rapido', '{"frase": "mientras =", "opciones": ["while", "when"], "correcta": 0, "es": "", "explicacion": "while = mientras; when = cuando.", "segundos": 6}'::jsonb, 'ep4-pasado-progresivo', 'fluidez', false),
  ('examen-ep4-pasado-progresivo-01', 'examen-ep4', 16, 'elegir', '{"frase": "He ___ a shower when the lights went out.", "opciones": ["took", "was taking", "were taking"], "correcta": 1, "es": "Se estaba bañando cuando se fue la luz.", "explicacion": "Acción interrumpida: was + -ing."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', true),
  ('examen-ep4-pasado-progresivo-02', 'examen-ep4', 17, 'elegir', '{"frase": "While we ___ , it started to rain.", "opciones": ["walked", "were walking", "was walking"], "correcta": 1, "es": "Mientras caminábamos, empezó a llover.", "explicacion": "While + were + -ing."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', true),
  ('examen-ep4-pasado-progresivo-03', 'examen-ep4', 18, 'escribir', '{"respuestas": ["they werent listening", "they were not listening"], "mostrar": "They weren''t listening.", "es": "Ellos no estaban escuchando.", "explicacion": "weren''t + listening."}'::jsonb, 'ep4-pasado-progresivo', 'estudio', true),
  ('ep4-speak-talk-01', 'ep4-speak-talk', 1, 'elegir', '{"frase": "Do you ___ English?", "opciones": ["speak", "say", "talk"], "correcta": 0, "es": "¿Hablas inglés?", "explicacion": "Idiomas → speak."}'::jsonb, 'ep4-speak-talk', 'estudio', false),
  ('ep4-speak-talk-02', 'ep4-speak-talk', 2, 'elegir', '{"frase": "I need to ___ to my wife about the business.", "opciones": ["speak in", "say", "talk"], "correcta": 2, "es": "Necesito hablar con mi esposa sobre el negocio.", "explicacion": "Conversar con alguien → talk to."}'::jsonb, 'ep4-speak-talk', 'estudio', false),
  ('ep4-speak-talk-03', 'ep4-speak-talk', 3, 'elegir', '{"frase": "May I ___ to Mr. Brown, please?", "opciones": ["tell", "speak", "say"], "correcta": 1, "es": "¿Puedo hablar con el señor Brown, por favor?", "explicacion": "Al teléfono formal: May I speak to…?"}'::jsonb, 'ep4-speak-talk', 'estudio', false),
  ('ep4-speak-talk-04', 'ep4-speak-talk', 4, 'elegir', '{"frase": "We ___ for hours last night.", "opciones": ["spoke English", "talked", "said"], "correcta": 1, "es": "Hablamos por horas anoche.", "explicacion": "Conversar mucho tiempo → talk (talked)."}'::jsonb, 'ep4-speak-talk', 'estudio', false),
  ('ep4-speak-talk-05', 'ep4-speak-talk', 5, 'escribir', '{"respuestas": ["she speaks french very well"], "mostrar": "She speaks French very well.", "es": "Ella habla francés muy bien.", "explicacion": "Idioma → speaks."}'::jsonb, 'ep4-speak-talk', 'estudio', false),
  ('ep4-speak-talk-06', 'ep4-speak-talk', 6, 'ordenar', '{"frase": "Can I speak to the manager please", "es": "¿Puedo hablar con el gerente, por favor?", "explicacion": "Petición formal al teléfono."}'::jsonb, 'ep4-speak-talk', 'estudio', false)
insert into ejercicios (id, leccion_id, orden, tipo, datos, tema_id, pata, reservado) values
  ('ep4-speak-talk-07', 'ep4-speak-talk', 7, 'emparejar', '{"pares": [["speak English", "hablar inglés"], ["talk to a friend", "hablar con un amigo"], ["Who''s speaking?", "¿Quién habla? (teléfono)"], ["spoke", "pasado de speak"]], "es": "", "explicacion": "speak, spoke, spoken · talk, talked, talked."}'::jsonb, 'ep4-speak-talk', 'estudio', false),
  ('ep4-speak-talk-08', 'ep4-speak-talk', 8, 'escuchar', '{"opciones": ["Could I speak to the receptionist?", "Could I talk the receptionist?", "Can you speak the receptionist?"], "correcta": 0, "audio": "Could I speak to the receptionist?", "es": "¿Podría hablar con la recepcionista?", "explicacion": "speak to + persona en una llamada formal."}'::jsonb, 'ep4-speak-talk', 'estudio', false),
  ('banco-ep4-speak-talk-01', 'banco-ep4', 49, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Receptionist: Grand Hotel, good morning. How can I help you?", "es": "Recepcionista: Grand Hotel, buenos días. ¿En qué le puedo ayudar?"}, {"en": "Caller: Good morning. May I speak to the manager, please?", "es": "Persona: Buenos días. ¿Puedo hablar con el gerente, por favor?"}, {"en": "Receptionist: One moment, please. Who''s speaking?", "es": "Recepcionista: Un momento, por favor. ¿Quién habla?"}], "pregunta": "Who does the caller want to speak to?", "pregunta_es": "¿Con quién quiere hablar la persona que llama?", "opciones": ["The manager.", "The receptionist.", "A guest."], "correcta": 0, "explicacion": "May I speak to the manager?"}'::jsonb, 'ep4-speak-talk', 'input', false),
  ('banco-ep4-speak-talk-02', 'banco-ep4', 50, 'comprension', '{"modo": "leer", "lineas": [{"en": "Paula speaks three languages: Spanish, English and Portuguese.", "es": "Paula habla tres idiomas: español, inglés y portugués."}, {"en": "Every evening she talks to her mother on the phone.", "es": "Todas las noches habla con su mamá por teléfono."}, {"en": "They talk about work, family and food.", "es": "Hablan del trabajo, la familia y la comida."}], "pregunta": "How many languages does Paula speak?", "pregunta_es": "¿Cuántos idiomas habla Paula?", "opciones": ["Two.", "Four.", "Three."], "correcta": 2, "explicacion": "speaks three languages."}'::jsonb, 'ep4-speak-talk', 'input', false),
  ('banco-ep4-speak-talk-03', 'banco-ep4', 51, 'decir', '{"es": "¿Puedo hablar con María, por favor?", "respuestas": ["may i speak to maria please", "can i speak to maria please", "could i speak to maria please"], "mostrar": "May I speak to Maria, please?", "explicacion": "Al teléfono: May I speak to…?"}'::jsonb, 'ep4-speak-talk', 'output', false),
  ('banco-ep4-speak-talk-04', 'banco-ep4', 52, 'decir', '{"es": "Hablamos todos los días.", "respuestas": ["we talk every day"], "mostrar": "We talk every day.", "explicacion": "Conversar → talk."}'::jsonb, 'ep4-speak-talk', 'output', false),
  ('banco-ep4-speak-talk-05', 'banco-ep4', 53, 'libre', '{"pregunta": "Write a short formal phone call: you call a hotel to speak to the manager.", "pregunta_es": "Escribe una llamada formal corta: llamas a un hotel para hablar con el gerente.", "ejemplo": "Good morning. May I speak to the manager, please? This is Uwaldo Florez speaking. I''d like to talk about my reservation.", "criterio": "speak para pedir con quién hablar y para presentarte; talk about para el tema.", "explicacion": "speak para pedir con quién hablar y para presentarte; talk about para el tema."}'::jsonb, 'ep4-speak-talk', 'output', false),
  ('banco-ep4-speak-talk-06', 'banco-ep4', 54, 'rapido', '{"frase": "___ Spanish", "opciones": ["speak", "talk"], "correcta": 0, "es": "hablar español", "explicacion": "Idiomas → speak.", "segundos": 6}'::jsonb, 'ep4-speak-talk', 'fluidez', false),
  ('banco-ep4-speak-talk-07', 'banco-ep4', 55, 'rapido', '{"frase": "___ to my wife", "opciones": ["talk", "speak in"], "correcta": 0, "es": "hablar con mi esposa", "explicacion": "Conversar → talk to.", "segundos": 6}'::jsonb, 'ep4-speak-talk', 'fluidez', false),
