  ('examen-ep5-neither-nor-03', 'examen-ep5', 6, 'escribir', '{"respuestas": ["neither he nor she came", "neither him nor her came"], "mostrar": "Neither he nor she came.", "es": "Ni él ni ella vinieron.", "explicacion": "Neither… nor + verbo afirmativo."}'::jsonb, 'ep5-neither-nor', 'estudio', true),
  ('ep5-negativas-01', 'ep5-negativas', 1, 'elegir', '{"frase": "___ called today. The phone was quiet.", "opciones": ["Somebody", "Anybody", "Nobody"], "correcta": 2, "es": "Nadie llamó hoy.", "explicacion": "nobody = nadie (con verbo afirmativo)."}'::jsonb, 'ep5-negativas', 'estudio', false),
  ('ep5-negativas-02', 'ep5-negativas', 2, 'elegir', '{"frase": "I have ___ to wear!", "opciones": ["nothing", "anything", "something"], "correcta": 0, "es": "¡No tengo nada que ponerme!", "explicacion": "have nothing = no tener nada."}'::jsonb, 'ep5-negativas', 'estudio', false),
  ('ep5-negativas-03', 'ep5-negativas', 3, 'elegir', '{"frase": "She ___ drinks coffee in the evening.", "opciones": ["ever", "doesn''t never", "never"], "correcta": 2, "es": "Ella nunca toma café en la noche.", "explicacion": "never va solo; no se dice doesn''t never."}'::jsonb, 'ep5-negativas', 'estudio', false),
  ('ep5-negativas-04', 'ep5-negativas', 4, 'elegir', '{"frase": "___ of the clients complained.", "opciones": ["Nothing", "None", "Nobody"], "correcta": 1, "es": "Ninguno de los clientes se quejó.", "explicacion": "none of + grupo = ninguno de…"}'::jsonb, 'ep5-negativas', 'estudio', false),
  ('ep5-negativas-05', 'ep5-negativas', 5, 'escribir', '{"respuestas": ["there is nobody in the store", "theres nobody in the store", "there is no one in the store", "there isnt anybody in the store", "there is not anybody in the store", "there is nobody in the shop"], "mostrar": "There''s nobody in the store.", "es": "No hay nadie en la tienda.", "explicacion": "nobody con verbo afirmativo, o isn''t + anybody."}'::jsonb, 'ep5-negativas', 'estudio', false),
  ('ep5-negativas-06', 'ep5-negativas', 6, 'ordenar', '{"frase": "I have nowhere to go tonight", "es": "No tengo a dónde ir esta noche.", "explicacion": "nowhere = ninguna parte."}'::jsonb, 'ep5-negativas', 'estudio', false),
  ('ep5-negativas-07', 'ep5-negativas', 7, 'emparejar', '{"pares": [["nobody", "nadie"], ["nothing", "nada"], ["nowhere", "ninguna parte"], ["never", "nunca"]], "es": "", "explicacion": "En inglés solo hay UNA negación por frase."}'::jsonb, 'ep5-negativas', 'estudio', false),
  ('ep5-negativas-08', 'ep5-negativas', 8, 'escuchar', '{"opciones": ["Nobody knows her real name.", "Somebody knows her real name.", "Nobody knew her name."], "correcta": 0, "audio": "Nobody knows her real name.", "es": "Nadie sabe su verdadero nombre.", "explicacion": "Nobody + verbo afirmativo con -s."}'::jsonb, 'ep5-negativas', 'estudio', false),
  ('banco-ep5-negativas-01', 'banco-ep5', 17, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Manager: Is anybody in the office?", "es": "Gerente: ¿Hay alguien en la oficina?"}, {"en": "Guard: No, sir. There''s nobody here. Everybody went home.", "es": "Vigilante: No, señor. No hay nadie. Todos se fueron a casa."}, {"en": "Manager: OK. Please lock the door. Nothing can stay open.", "es": "Gerente: Bueno. Cierre con llave. Nada puede quedar abierto."}], "pregunta": "Is anyone in the office?", "pregunta_es": "¿Hay alguien en la oficina?", "opciones": ["Yes, the manager.", "No, there''s nobody.", "Yes, everybody."], "correcta": 1, "explicacion": "There''s nobody here = no hay nadie."}'::jsonb, 'ep5-negativas', 'input', false),
  ('banco-ep5-negativas-02', 'banco-ep5', 18, 'comprension', '{"modo": "leer", "lineas": [{"en": "John did nothing for the project.", "es": "John no hizo nada para el proyecto."}, {"en": "He never answered the emails, and none of his ideas were ready.", "es": "Nunca respondió los correos y ninguna de sus ideas estaba lista."}, {"en": "Nobody wants to work with him now.", "es": "Ahora nadie quiere trabajar con él."}], "pregunta": "What did John do for the project?", "pregunta_es": "¿Qué hizo John para el proyecto?", "opciones": ["He answered the emails.", "Nothing.", "Everything."], "correcta": 1, "explicacion": "did nothing = no hizo nada."}'::jsonb, 'ep5-negativas', 'input', false),
  ('banco-ep5-negativas-03', 'banco-ep5', 19, 'decir', '{"es": "Nunca trabajo los domingos.", "respuestas": ["i never work on sundays"], "mostrar": "I never work on Sundays.", "explicacion": "never + verbo afirmativo."}'::jsonb, 'ep5-negativas', 'output', false),
  ('banco-ep5-negativas-04', 'banco-ep5', 20, 'decir', '{"es": "Nadie sabe.", "respuestas": ["nobody knows", "no one knows"], "mostrar": "Nobody knows.", "explicacion": "nobody + knows."}'::jsonb, 'ep5-negativas', 'output', false),
  ('banco-ep5-negativas-05', 'banco-ep5', 21, 'libre', '{"pregunta": "Describe a bad day at work using at least three negative words (nobody, nothing, never, none, nowhere).", "pregunta_es": "Describe un mal día de trabajo usando al menos tres palabras negativas.", "ejemplo": "Yesterday was a bad day. Nobody came to the store. We sold nothing. None of the clients answered my messages.", "criterio": "Una sola negación por frase: nobody came (no: nobody didn''t come).", "explicacion": "Una sola negación por frase: nobody came (no: nobody didn''t come)."}'::jsonb, 'ep5-negativas', 'output', false),
  ('banco-ep5-negativas-06', 'banco-ep5', 22, 'rapido', '{"frase": "nadie =", "opciones": ["nobody", "anybody"], "correcta": 0, "es": "", "explicacion": "nobody = nadie.", "segundos": 6}'::jsonb, 'ep5-negativas', 'fluidez', false),
  ('banco-ep5-negativas-07', 'banco-ep5', 23, 'rapido', '{"frase": "nunca =", "opciones": ["never", "ever"], "correcta": 0, "es": "", "explicacion": "never = nunca.", "segundos": 6}'::jsonb, 'ep5-negativas', 'fluidez', false),
  ('banco-ep5-negativas-08', 'banco-ep5', 24, 'rapido', '{"frase": "I have ___ money.", "opciones": ["no", "not"], "correcta": 0, "es": "No tengo dinero.", "explicacion": "no + sustantivo.", "segundos": 6}'::jsonb, 'ep5-negativas', 'fluidez', false),
  ('examen-ep5-negativas-01', 'examen-ep5', 7, 'elegir', '{"frase": "I looked for my keys, but they were ___.", "opciones": ["anywhere", "nowhere", "nothing"], "correcta": 1, "es": "Busqué mis llaves, pero no estaban en ninguna parte.", "explicacion": "nowhere = en ninguna parte."}'::jsonb, 'ep5-negativas', 'estudio', true),
  ('examen-ep5-negativas-02', 'examen-ep5', 8, 'elegir', '{"frase": "There''s ___ in the fridge. Let''s go shopping.", "opciones": ["nobody", "anything", "nothing"], "correcta": 2, "es": "No hay nada en la nevera.", "explicacion": "nothing = nada."}'::jsonb, 'ep5-negativas', 'estudio', true),
  ('examen-ep5-negativas-03', 'examen-ep5', 9, 'escribir', '{"respuestas": ["nobody helped me", "no one helped me"], "mostrar": "Nobody helped me.", "es": "Nadie me ayudó.", "explicacion": "Nobody + verbo afirmativo en pasado."}'::jsonb, 'ep5-negativas', 'estudio', true),
  ('ep5-pronombres-objeto-01', 'ep5-pronombres-objeto', 1, 'elegir', '{"frase": "Can you help ___? I can''t open the box.", "opciones": ["me", "my", "I"], "correcta": 0, "es": "¿Me ayudas? No puedo abrir la caja.", "explicacion": "Después del verbo: me."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', false),
  ('ep5-pronombres-objeto-02', 'ep5-pronombres-objeto', 2, 'elegir', '{"frase": "I called Maria, but she didn''t answer ___ .", "opciones": ["me", "she", "her"], "correcta": 0, "es": "Llamé a María, pero no me contestó.", "explicacion": "answer me = contestarme."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', false),
  ('ep5-pronombres-objeto-03', 'ep5-pronombres-objeto', 3, 'elegir', '{"frase": "This gift is for my parents. I bought it for ___.", "opciones": ["they", "their", "them"], "correcta": 2, "es": "Este regalo es para mis papás. Lo compré para ellos.", "explicacion": "Después de for: them."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', false),
  ('ep5-pronombres-objeto-04', 'ep5-pronombres-objeto', 4, 'elegir', '{"frase": "Where is Carlos? I need to talk to ___.", "opciones": ["him", "he", "his"], "correcta": 0, "es": "¿Dónde está Carlos? Necesito hablar con él.", "explicacion": "Después de to: him."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', false),
  ('ep5-pronombres-objeto-05', 'ep5-pronombres-objeto', 5, 'escribir', '{"respuestas": ["she called us yesterday", "yesterday she called us"], "mostrar": "She called us yesterday.", "es": "Ella nos llamó ayer.", "explicacion": "nosotros (objeto) = us."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', false),
  ('ep5-pronombres-objeto-06', 'ep5-pronombres-objeto', 6, 'ordenar', '{"frase": "Please send them the invoice today", "es": "Por favor envíales la factura hoy.", "explicacion": "send + them + cosa."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', false),
  ('ep5-pronombres-objeto-07', 'ep5-pronombres-objeto', 7, 'emparejar', '{"pares": [["I → me", "yo → me / mí"], ["he → him", "él → lo / le"], ["she → her", "ella → la / le"], ["we → us", "nosotros → nos"]], "es": "", "explicacion": "Sujeto a la izquierda, objeto a la derecha."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', false),
  ('ep5-pronombres-objeto-08', 'ep5-pronombres-objeto', 8, 'escuchar', '{"opciones": ["I love them and I miss them.", "I love him and I miss him.", "I love you and I miss you."], "correcta": 2, "audio": "I love you and I miss you.", "es": "Te amo y te extraño.", "explicacion": "you es igual como sujeto y como objeto."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', false),
  ('banco-ep5-pronombres-objeto-01', 'banco-ep5', 25, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Secretary: Mr. Ruiz called. He wants to see you.", "es": "Secretaria: Llamó el señor Ruiz. Quiere verlo."}, {"en": "Boss: OK. Tell him to come at three.", "es": "Jefe: Bueno. Dígale que venga a las tres."}, {"en": "Boss: And please give me the reports.", "es": "Jefe: Y por favor deme los informes."}], "pregunta": "What does the boss want?", "pregunta_es": "¿Qué quiere el jefe?", "opciones": ["The reports.", "To call Mr. Ruiz.", "To go home."], "correcta": 0, "explicacion": "give me the reports = deme los informes."}'::jsonb, 'ep5-pronombres-objeto', 'input', false),
  ('banco-ep5-pronombres-objeto-02', 'banco-ep5', 26, 'comprension', '{"modo": "leer", "lineas": [{"en": "My daughter loves her grandparents.", "es": "Mi hija ama a sus abuelos."}, {"en": "She visits them every Sunday and they cook for her.", "es": "Los visita cada domingo y ellos cocinan para ella."}, {"en": "They always give her candy, so she loves them even more!", "es": "Siempre le dan dulces, ¡así que los quiere aún más!"}], "pregunta": "What do the grandparents give her?", "pregunta_es": "¿Qué le dan los abuelos?", "opciones": ["Shoes.", "Candy.", "Money."], "correcta": 1, "explicacion": "give her candy = le dan dulces."}'::jsonb, 'ep5-pronombres-objeto', 'input', false),
  ('banco-ep5-pronombres-objeto-03', 'banco-ep5', 27, 'decir', '{"es": "Llámame mañana.", "respuestas": ["call me tomorrow"], "mostrar": "Call me tomorrow.", "explicacion": "call + me."}'::jsonb, 'ep5-pronombres-objeto', 'output', false),
  ('banco-ep5-pronombres-objeto-04', 'banco-ep5', 28, 'decir', '{"es": "Lo vi ayer. (a él)", "respuestas": ["i saw him yesterday"], "mostrar": "I saw him yesterday.", "explicacion": "see → saw + him."}'::jsonb, 'ep5-pronombres-objeto', 'output', false),
  ('banco-ep5-pronombres-objeto-05', 'banco-ep5', 29, 'libre', '{"pregunta": "Write three sentences about people you help or who help you. Use object pronouns.", "pregunta_es": "Escribe tres frases sobre personas a las que ayudas o que te ayudan. Usa pronombres objeto.", "ejemplo": "My wife helps me with the store. I help her with the deliveries. Our clients call us every day.", "criterio": "Pronombres objeto después del verbo o preposición (me, her, us, them).", "explicacion": "Pronombres objeto después del verbo o preposición (me, her, us, them)."}'::jsonb, 'ep5-pronombres-objeto', 'output', false),
  ('banco-ep5-pronombres-objeto-06', 'banco-ep5', 30, 'rapido', '{"frase": "help ___ (a mí)", "opciones": ["me", "I"], "correcta": 0, "es": "ayúdame", "explicacion": "Objeto: me.", "segundos": 6}'::jsonb, 'ep5-pronombres-objeto', 'fluidez', false),
  ('banco-ep5-pronombres-objeto-07', 'banco-ep5', 31, 'rapido', '{"frase": "with ___ (ellos)", "opciones": ["they", "them"], "correcta": 1, "es": "con ellos", "explicacion": "Después de preposición: them.", "segundos": 6}'::jsonb, 'ep5-pronombres-objeto', 'fluidez', false),
  ('banco-ep5-pronombres-objeto-08', 'banco-ep5', 32, 'rapido', '{"frase": "for ___ (nosotros)", "opciones": ["us", "we"], "correcta": 0, "es": "para nosotros", "explicacion": "Objeto: us.", "segundos": 6}'::jsonb, 'ep5-pronombres-objeto', 'fluidez', false),
  ('examen-ep5-pronombres-objeto-01', 'examen-ep5', 10, 'elegir', '{"frase": "I know Laura. I work with ___.", "opciones": ["her", "hers", "she"], "correcta": 0, "es": "Conozco a Laura. Trabajo con ella.", "explicacion": "with + her."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', true),
  ('examen-ep5-pronombres-objeto-02', 'examen-ep5', 11, 'elegir', '{"frase": "Our clients are great. We love ___.", "opciones": ["them", "they", "their"], "correcta": 0, "es": "Nuestros clientes son geniales. Los queremos.", "explicacion": "love + them."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', true),
  ('examen-ep5-pronombres-objeto-03', 'examen-ep5', 12, 'escribir', '{"respuestas": ["can you call him", "could you call him"], "mostrar": "Can you call him?", "es": "¿Puedes llamarlo? (a él)", "explicacion": "call + him."}'::jsonb, 'ep5-pronombres-objeto', 'estudio', true),
  ('ep5-oficina-01', 'ep5-oficina', 1, 'elegir', '{"frase": "I can''t print. The ___ is out of paper.", "opciones": ["screen", "keyboard", "printer"], "correcta": 2, "es": "No puedo imprimir. La impresora no tiene papel.", "explicacion": "printer = impresora."}'::jsonb, 'ep5-oficina', 'estudio', false),
  ('ep5-oficina-02', 'ep5-oficina', 2, 'elegir', '{"frase": "Please ___ the file before you close it.", "opciones": ["keep out", "save", "safe"], "correcta": 1, "es": "Por favor guarda el archivo antes de cerrarlo.", "explicacion": "save = guardar (archivo)."}'::jsonb, 'ep5-oficina', 'estudio', false),
  ('ep5-oficina-03', 'ep5-oficina', 3, 'elegir', '{"frase": "You type with the ___.", "opciones": ["mouse", "chair", "keyboard"], "correcta": 2, "es": "Se escribe con el teclado.", "explicacion": "keyboard = teclado."}'::jsonb, 'ep5-oficina', 'estudio', false),
  ('ep5-oficina-04', 'ep5-oficina', 4, 'elegir', '{"frase": "We have a ___ with the team at 9 a.m.", "opciones": ["meeting", "reunion", "date"], "correcta": 0, "es": "Tenemos una reunión con el equipo a las 9 a. m.", "explicacion": "meeting = reunión de trabajo (reunion es un reencuentro)."}'::jsonb, 'ep5-oficina', 'estudio', false),
  ('ep5-oficina-05', 'ep5-oficina', 5, 'escribir', '{"respuestas": ["my computer is slow", "my laptop is slow"], "mostrar": "My computer is slow.", "es": "Mi computador es lento.", "explicacion": "slow = lento."}'::jsonb, 'ep5-oficina', 'estudio', false),
  ('ep5-oficina-06', 'ep5-oficina', 6, 'ordenar', '{"frase": "The folder is on my desk", "es": "La carpeta está en mi escritorio.", "explicacion": "on my desk = sobre mi escritorio."}'::jsonb, 'ep5-oficina', 'estudio', false),
  ('ep5-oficina-07', 'ep5-oficina', 7, 'emparejar', '{"pares": [["desk", "escritorio"], ["screen", "pantalla"], ["mouse", "ratón"], ["folder", "carpeta"]], "es": "", "explicacion": "Palabras de oficina."}'::jsonb, 'ep5-oficina', 'estudio', false),
  ('ep5-oficina-08', 'ep5-oficina', 8, 'escuchar', '{"opciones": ["Click on the icon and open the file.", "Click on the mouse and open the folder.", "Click on the icon and close the file."], "correcta": 0, "audio": "Click on the icon and open the file.", "es": "Haz clic en el ícono y abre el archivo.", "explicacion": "open = abrir; close = cerrar."}'::jsonb, 'ep5-oficina', 'estudio', false),
  ('banco-ep5-oficina-01', 'banco-ep5', 33, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Assistant: The printer isn''t working.", "es": "Asistente: La impresora no funciona."}, {"en": "Manager: Did you turn it on?", "es": "Gerente: ¿La encendiste?"}, {"en": "Assistant: Yes, but there''s no ink.", "es": "Asistente: Sí, pero no hay tinta."}], "pregunta": "What''s the problem with the printer?", "pregunta_es": "¿Cuál es el problema con la impresora?", "opciones": ["There''s no ink.", "It''s off.", "There''s no paper."], "correcta": 0, "explicacion": "there''s no ink = no hay tinta."}'::jsonb, 'ep5-oficina', 'input', false),
  ('banco-ep5-oficina-02', 'banco-ep5', 34, 'comprension', '{"modo": "leer", "lineas": [{"en": "Uwaldo''s desk has a laptop, a big screen and a keyboard.", "es": "El escritorio de Uwaldo tiene un portátil, una pantalla grande y un teclado."}, {"en": "He keeps the invoices in a blue folder.", "es": "Guarda las facturas en una carpeta azul."}, {"en": "Every Friday he sends a report by email.", "es": "Cada viernes envía un informe por correo."}], "pregunta": "Where does he keep the invoices?", "pregunta_es": "¿Dónde guarda las facturas?", "opciones": ["In his email.", "In a blue folder.", "On the screen."], "correcta": 1, "explicacion": "in a blue folder = en una carpeta azul."}'::jsonb, 'ep5-oficina', 'input', false),
  ('banco-ep5-oficina-03', 'banco-ep5', 35, 'decir', '{"es": "La impresora no funciona.", "respuestas": ["the printer doesnt work", "the printer does not work", "the printer isnt working", "the printer is not working"], "mostrar": "The printer isn''t working.", "explicacion": "isn''t working = no está funcionando."}'::jsonb, 'ep5-oficina', 'output', false),
  ('banco-ep5-oficina-04', 'banco-ep5', 36, 'decir', '{"es": "Envíame el archivo por correo.", "respuestas": ["send me the file by email"], "mostrar": "Send me the file by email.", "explicacion": "by email = por correo."}'::jsonb, 'ep5-oficina', 'output', false)
insert into ejercicios (id, leccion_id, orden, tipo, datos, tema_id, pata, reservado) values
  ('banco-ep5-oficina-05', 'banco-ep5', 37, 'libre', '{"pregunta": "Describe your desk or work space: what things are there and what you use them for.", "pregunta_es": "Describe tu escritorio o lugar de trabajo: qué cosas hay y para qué las usas.", "ejemplo": "On my desk there is a laptop, a mouse and a printer. I use the laptop to answer clients. I print the invoices.", "criterio": "Vocabulario de oficina y frases claras (there is / I use … to …).", "explicacion": "Vocabulario de oficina y frases claras (there is / I use … to …)."}'::jsonb, 'ep5-oficina', 'output', false),
  ('banco-ep5-oficina-06', 'banco-ep5', 38, 'rapido', '{"frase": "teclado =", "opciones": ["keyboard", "keyword"], "correcta": 0, "es": "", "explicacion": "keyboard = teclado.", "segundos": 6}'::jsonb, 'ep5-oficina', 'fluidez', false),
  ('banco-ep5-oficina-07', 'banco-ep5', 39, 'rapido', '{"frase": "guardar (archivo) =", "opciones": ["save", "safe"], "correcta": 0, "es": "", "explicacion": "save = guardar.", "segundos": 6}'::jsonb, 'ep5-oficina', 'fluidez', false),
  ('banco-ep5-oficina-08', 'banco-ep5', 40, 'rapido', '{"frase": "reunión de trabajo =", "opciones": ["meeting", "reunion"], "correcta": 0, "es": "", "explicacion": "meeting = reunión.", "segundos": 6}'::jsonb, 'ep5-oficina', 'fluidez', false),
  ('examen-ep5-oficina-01', 'examen-ep5', 13, 'elegir', '{"frase": "Look at the ___ . The numbers are there.", "opciones": ["keyboard", "screen", "chair"], "correcta": 1, "es": "Mira la pantalla. Ahí están los números.", "explicacion": "screen = pantalla."}'::jsonb, 'ep5-oficina', 'estudio', true),
  ('examen-ep5-oficina-02', 'examen-ep5', 14, 'elegir', '{"frase": "Please ___ ten copies of the report.", "opciones": ["type", "save", "print"], "correcta": 2, "es": "Por favor imprime diez copias del informe.", "explicacion": "print = imprimir."}'::jsonb, 'ep5-oficina', 'estudio', true),
  ('examen-ep5-oficina-03', 'examen-ep5', 15, 'escribir', '{"respuestas": ["i have a meeting at three", "i have a meeting at 3", "ive got a meeting at three", "i have got a meeting at three"], "mostrar": "I have a meeting at three.", "es": "Tengo una reunión a las tres.", "explicacion": "meeting = reunión."}'::jsonb, 'ep5-oficina', 'estudio', true),
  ('ep5-there-is-01', 'ep5-there-is', 1, 'elegir', '{"frase": "___ a bank near the hotel.", "opciones": ["There is", "It has", "There are"], "correcta": 0, "es": "Hay un banco cerca del hotel.", "explicacion": "Singular → there is."}'::jsonb, 'ep5-there-is', 'estudio', false),
  ('ep5-there-is-02', 'ep5-there-is', 2, 'elegir', '{"frase": "___ twenty pairs of shoes in the window.", "opciones": ["There are", "They are", "There is"], "correcta": 0, "es": "Hay veinte pares de zapatos en la vitrina.", "explicacion": "Plural → there are."}'::jsonb, 'ep5-there-is', 'estudio', false),
