  ('banco-ep6-contables-01', 'banco-ep6', 1, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Waiter: Would you like some bread?", "es": "Mesero: ¿Desea pan?"}, {"en": "Customer: Yes, please. And a glass of orange juice.", "es": "Cliente: Sí, por favor. Y un vaso de jugo de naranja."}, {"en": "Waiter: Sorry, we have no orange juice. We have lemonade.", "es": "Mesero: Lo siento, no hay jugo de naranja. Tenemos limonada."}], "pregunta": "What drink is there?", "pregunta_es": "¿Qué bebida hay?", "opciones": ["Lemonade.", "Orange juice.", "Water."], "correcta": 0, "explicacion": "We have lemonade."}'::jsonb, 'ep6-contables', 'input', false),
  ('banco-ep6-contables-02', 'banco-ep6', 2, 'comprension', '{"modo": "leer", "lineas": [{"en": "For the party we bought two kilos of rice, ten eggs and some cheese.", "es": "Para la fiesta compramos dos kilos de arroz, diez huevos y algo de queso."}, {"en": "We also need a lot of ice and three bottles of soda.", "es": "También necesitamos mucho hielo y tres botellas de gaseosa."}, {"en": "The meat is in the fridge.", "es": "La carne está en la nevera."}], "pregunta": "How many eggs did they buy?", "pregunta_es": "¿Cuántos huevos compraron?", "opciones": ["Three.", "Two.", "Ten."], "correcta": 2, "explicacion": "ten eggs = diez huevos."}'::jsonb, 'ep6-contables', 'input', false),
