  ('banco-ep6-contables-05', 'banco-ep6', 5, 'libre', '{"pregunta": "Write your shopping list for a family lunch: four countable and four uncountable things, with quantities.", "pregunta_es": "Escribe tu lista de mercado para un almuerzo familiar: cuatro cosas contables y cuatro incontables, con cantidades.", "ejemplo": "Two chickens, six potatoes, four tomatoes, one onion. A bag of rice, a bottle of oil, some salt and a liter of milk.", "criterio": "Contables con número y plural; incontables con medida (a bag of, a bottle of, some).", "explicacion": "Contables con número y plural; incontables con medida (a bag of, a bottle of, some)."}'::jsonb, 'ep6-contables', 'output', false),
  ('banco-ep6-contables-06', 'banco-ep6', 6, 'rapido', '{"frase": "___ money", "opciones": ["some", "a"], "correcta": 0, "es": "algo de dinero", "explicacion": "Incontable.", "segundos": 6}'::jsonb, 'ep6-contables', 'fluidez', false),
  ('banco-ep6-contables-07', 'banco-ep6', 7, 'rapido', '{"frase": "two ___", "opciones": ["eggs", "egg"], "correcta": 0, "es": "dos huevos", "explicacion": "Contable plural.", "segundos": 6}'::jsonb, 'ep6-contables', 'fluidez', false),
  ('banco-ep6-contables-08', 'banco-ep6', 8, 'rapido', '{"frase": "advice es…", "opciones": ["contable", "incontable"], "correcta": 1, "es": "consejo", "explicacion": "advice no lleva -s.", "segundos": 6}'::jsonb, 'ep6-contables', 'fluidez', false),
