  ('examen-ep6-contables-02', 'examen-ep6', 2, 'elegir', '{"frase": "I''d like a ___ of milk.", "opciones": ["milk", "piece", "glass"], "correcta": 2, "es": "Quisiera un vaso de leche.", "explicacion": "a glass of milk."}'::jsonb, 'ep6-contables', 'estudio', true),
  ('examen-ep6-contables-03', 'examen-ep6', 3, 'escribir', '{"respuestas": ["i bought two bottles of oil"], "mostrar": "I bought two bottles of oil.", "es": "Compré dos botellas de aceite.", "explicacion": "two bottles of + incontable."}'::jsonb, 'ep6-contables', 'estudio', true),
  ('ep6-some-any-01', 'ep6-some-any', 1, 'elegir', '{"frase": "I have ___ friends in Bogotá.", "opciones": ["a", "any", "some"], "correcta": 2, "es": "Tengo algunos amigos en Bogotá.", "explicacion": "Afirmativa → some."}'::jsonb, 'ep6-some-any', 'estudio', false),
