  ('ep6-some-any-07', 'ep6-some-any', 7, 'emparejar', '{"pares": [["some (afirmativa)", "algunos / algo de"], ["any (negativa)", "ningún / nada de"], ["any (pregunta)", "¿algún…?"], ["Would you like some…?", "¿Quieres…? (ofrecer)"]], "es": "", "explicacion": "some = sí hay; any = no hay o pregunto."}'::jsonb, 'ep6-some-any', 'estudio', false),
