  ('banco-ep6-some-any-02', 'banco-ep6', 10, 'comprension', '{"modo": "leer", "lineas": [{"en": "Natalia hasn''t got any friends in Athens.", "es": "Natalia no tiene amigos en Atenas."}, {"en": "But she has some cousins there.", "es": "Pero tiene algunos primos allá."}, {"en": "Are there any good places to visit? Yes, a lot!", "es": "¿Hay buenos lugares para visitar? ¡Sí, muchos!"}], "pregunta": "Who does Natalia have in Athens?", "pregunta_es": "¿A quién tiene Natalia en Atenas?", "opciones": ["Some friends.", "Some cousins.", "Nobody."], "correcta": 1, "explicacion": "she has some cousins there."}'::jsonb, 'ep6-some-any', 'input', false),
