  ('banco-ep6-some-any-05', 'banco-ep6', 13, 'libre', '{"pregunta": "Look in your fridge (or imagine it). Write what there is (some) and what there isn''t (any).", "pregunta_es": "Mira tu nevera (o imagínala). Escribe qué hay (some) y qué no hay (any).", "ejemplo": "There is some milk and some cheese. There are some eggs. There isn''t any meat. There aren''t any tomatoes.", "criterio": "some en afirmativas; any en negativas y preguntas.", "explicacion": "some en afirmativas; any en negativas y preguntas."}'::jsonb, 'ep6-some-any', 'output', false),
