  ('examen-ep6-some-any-03', 'examen-ep6', 6, 'escribir', '{"respuestas": ["do you know any good restaurants near here", "are there any good restaurants near here", "is there any good restaurant near here", "do you have any good restaurants near here"], "mostrar": "Are there any good restaurants near here?", "es": "¿Tienes algún buen restaurante cerca?", "explicacion": "Pregunta → any."}'::jsonb, 'ep6-some-any', 'estudio', true),
