  ('banco-ep6-cuantificadores-01', 'banco-ep6', 17, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Mom: To make an apple pie we need a lot of apples.", "es": "Mamá: Para el pie de manzana necesitamos muchas manzanas."}, {"en": "Mom: We also need some flour, a little butter and a few eggs.", "es": "Mamá: También harina, un poco de mantequilla y unos pocos huevos."}, {"en": "Daughter: How much sugar? — Just a cup.", "es": "Hija: ¿Cuánta azúcar? — Solo una taza."}], "pregunta": "How much sugar do they need?", "pregunta_es": "¿Cuánta azúcar necesitan?", "opciones": ["Just a cup.", "A lot of sugar.", "A few eggs."], "correcta": 0, "explicacion": "Just a cup = solo una taza."}'::jsonb, 'ep6-cuantificadores', 'input', false),
