  ('banco-ep6-cuantificadores-05', 'banco-ep6', 21, 'libre', '{"pregunta": "Describe a normal week in your business with much, many, a lot of, a few and a little.", "pregunta_es": "Describe una semana normal en tu negocio con much, many, a lot of, a few y a little.", "ejemplo": "On Saturdays we have a lot of clients. On Mondays only a few people come. I don''t have much free time, but I study a little every day.", "criterio": "many/few con contables; much/little con incontables; a lot of con los dos.", "explicacion": "many/few con contables; much/little con incontables; a lot of con los dos."}'::jsonb, 'ep6-cuantificadores', 'output', false),
