  ('banco-ep6-frecuencia-03', 'banco-ep6', 51, 'decir', '{"es": "Siempre estoy cansado los lunes.", "respuestas": ["i am always tired on mondays", "im always tired on mondays"], "mostrar": "I''m always tired on Mondays.", "explicacion": "Después de be: am always."}'::jsonb, 'ep6-frecuencia', 'output', false),
  ('banco-ep6-frecuencia-04', 'banco-ep6', 52, 'decir', '{"es": "A veces trabajo los domingos.", "respuestas": ["sometimes i work on sundays", "i sometimes work on sundays"], "mostrar": "I sometimes work on Sundays.", "explicacion": "sometimes puede ir al inicio o antes del verbo."}'::jsonb, 'ep6-frecuencia', 'output', false),
  ('banco-ep6-frecuencia-05', 'banco-ep6', 53, 'libre', '{"pregunta": "Write about your weekly routine with five different adverbs of frequency.", "pregunta_es": "Escribe sobre tu rutina semanal con cinco adverbios de frecuencia distintos.", "ejemplo": "I always open the store at nine. I usually have lunch at one. I often do lives on TikTok. I sometimes go to the gym. I never work on Sunday mornings.", "criterio": "Adverbio antes del verbo principal y después de to be.", "explicacion": "Adverbio antes del verbo principal y después de to be."}'::jsonb, 'ep6-frecuencia', 'output', false),
  ('banco-ep6-frecuencia-06', 'banco-ep6', 54, 'rapido', '{"frase": "nunca =", "opciones": ["never", "ever"], "correcta": 0, "es": "", "explicacion": "never = nunca.", "segundos": 6}'::jsonb, 'ep6-frecuencia', 'fluidez', false),
  ('banco-ep6-frecuencia-07', 'banco-ep6', 55, 'rapido', '{"frase": "I am ___ tired.", "opciones": ["alway", "always"], "correcta": 1, "es": "Siempre estoy cansado.", "explicacion": "always.", "segundos": 6}'::jsonb, 'ep6-frecuencia', 'fluidez', false),
  ('banco-ep6-frecuencia-08', 'banco-ep6', 56, 'rapido', '{"frase": "casi nunca =", "opciones": ["almost always", "hardly ever"], "correcta": 1, "es": "", "explicacion": "hardly ever.", "segundos": 6}'::jsonb, 'ep6-frecuencia', 'fluidez', false),
  ('examen-ep6-frecuencia-01', 'examen-ep6', 19, 'elegir', '{"frase": "Choose the correct order:", "opciones": ["Seldom they go out in the week.", "They go seldom out in the week.", "They seldom go out in the week."], "correcta": 2, "es": "Rara vez salen entre semana.", "explicacion": "Adverbio antes del verbo."}'::jsonb, 'ep6-frecuencia', 'estudio', true),
  ('examen-ep6-frecuencia-02', 'examen-ep6', 20, 'elegir', '{"frase": "Our classroom isn''t ___ clean.", "opciones": ["never", "always", "ever"], "correcta": 1, "es": "Nuestro salón no siempre está limpio.", "explicacion": "isn''t always = no siempre."}'::jsonb, 'ep6-frecuencia', 'estudio', true),
  ('examen-ep6-frecuencia-03', 'examen-ep6', 21, 'escribir', '{"respuestas": ["do you always go out on fridays", "do you always go out on friday"], "mostrar": "Do you always go out on Fridays?", "es": "¿Siempre sales los viernes?", "explicacion": "Do + you + always + verbo."}'::jsonb, 'ep6-frecuencia', 'estudio', true),
