  ('ep6-something-03', 'ep6-something', 3, 'elegir', '{"frase": "Did you meet ___ at the party?", "opciones": ["nowhere", "anyone", "someone"], "correcta": 1, "es": "¿Conociste a alguien en la fiesta?", "explicacion": "Pregunta → anyone."}'::jsonb, 'ep6-something', 'estudio', false),
