  ('ep6-something-07', 'ep6-something', 7, 'emparejar', '{"pares": [["something", "algo"], ["someone", "alguien"], ["somewhere", "algún lugar"], ["anything (negativa)", "nada"]], "es": "", "explicacion": "some- = afirmativa; any- = pregunta o negativa."}'::jsonb, 'ep6-something', 'estudio', false),
