  ('banco-ep6-something-02', 'banco-ep6', 58, 'comprension', '{"modo": "leer", "lineas": [{"en": "When I''m bored, I try to go out somewhere.", "es": "Cuando estoy aburrido, trato de salir a algún lugar."}, {"en": "Sometimes I call someone from my family.", "es": "A veces llamo a alguien de mi familia."}, {"en": "I never stay at home doing nothing.", "es": "Nunca me quedo en casa sin hacer nada."}], "pregunta": "What does he do when he''s bored?", "pregunta_es": "¿Qué hace cuando está aburrido?", "opciones": ["He stays at home.", "He does nothing.", "He goes out somewhere."], "correcta": 2, "explicacion": "go out somewhere."}'::jsonb, 'ep6-something', 'input', false),
  ('banco-ep6-something-03', 'banco-ep6', 59, 'decir', '{"es": "Alguien me llamó.", "respuestas": ["someone called me", "somebody called me"], "mostrar": "Someone called me.", "explicacion": "Afirmativa → someone."}'::jsonb, 'ep6-something', 'output', false),
  ('banco-ep6-something-04', 'banco-ep6', 60, 'decir', '{"es": "No sé nada.", "respuestas": ["i dont know anything", "i do not know anything", "i know nothing"], "mostrar": "I don''t know anything.", "explicacion": "Negativa → anything."}'::jsonb, 'ep6-something', 'output', false),
  ('banco-ep6-something-05', 'banco-ep6', 61, 'libre', '{"pregunta": "Write about last weekend: something you did, someone you saw, somewhere you went, and something you didn''t do (anything).", "pregunta_es": "Escribe sobre el fin de semana pasado: algo que hiciste, alguien que viste, un lugar al que fuiste y algo que no hiciste (anything).", "ejemplo": "On Saturday I bought something for my daughter. I saw someone from the police. We went somewhere new for lunch. On Sunday I didn''t do anything.", "criterio": "some- en afirmativas; any- en negativas y preguntas.", "explicacion": "some- en afirmativas; any- en negativas y preguntas."}'::jsonb, 'ep6-something', 'output', false),
