  ('banco-ep7-preposiciones-02', 'banco-ep7', 2, 'comprension', '{"modo": "leer", "lineas": [{"en": "My little girl goes to school in the morning.", "es": "Mi niña va al colegio en la mañana."}, {"en": "In the afternoon she plays with her cousins.", "es": "En la tarde juega con sus primos."}, {"en": "On Saturdays she comes to the store with us.", "es": "Los sábados viene a la tienda con nosotros."}], "pregunta": "When does she come to the store?", "pregunta_es": "¿Cuándo viene a la tienda?", "opciones": ["On Saturdays.", "In the morning.", "In the afternoon."], "correcta": 0, "explicacion": "On Saturdays."}'::jsonb, 'ep7-preposiciones', 'input', false),
