  ('banco-ep7-preposiciones-04', 'banco-ep7', 4, 'decir', '{"es": "Vivo en Cúcuta con mi familia.", "respuestas": ["i live in cucuta with my family", "i live in cúcuta with my family"], "mostrar": "I live in Cúcuta with my family.", "explicacion": "in + ciudad; with = con."}'::jsonb, 'ep7-preposiciones', 'output', false),
  ('banco-ep7-preposiciones-05', 'banco-ep7', 5, 'libre', '{"pregunta": "Describe your typical Saturday with at least five prepositions (at, on, in, from, to, by, with, for).", "pregunta_es": "Describe tu sábado típico con al menos cinco preposiciones.", "ejemplo": "On Saturdays I open the store at nine. I work from nine to six with my wife. At noon we eat in a small restaurant. I go home by motorcycle.", "criterio": "Preposiciones de tiempo y lugar correctas.", "explicacion": "Preposiciones de tiempo y lugar correctas."}'::jsonb, 'ep7-preposiciones', 'output', false),
