  ('ep7-posesivo-s-08', 'ep7-posesivo-s', 8, 'escuchar', '{"opciones": ["That''s my wives'' store.", "That''s my wife store.", "That''s my wife''s store."], "correcta": 2, "audio": "That''s my wife''s store.", "es": "Esa es la tienda de mi esposa.", "explicacion": "wife''s = de mi esposa."}'::jsonb, 'ep7-posesivo-s', 'estudio', false),
  ('banco-ep7-posesivo-s-01', 'banco-ep7', 9, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Bartender: Whose jacket is this?", "es": "Bartender: ¿De quién es esta chaqueta?"}, {"en": "Customer: It''s my friend''s. He went to the bathroom.", "es": "Cliente: Es de mi amigo. Fue al baño."}, {"en": "Bartender: And these glasses? — They''re the girls'' drinks.", "es": "Bartender: ¿Y estos vasos? — Son las bebidas de las chicas."}], "pregunta": "Whose jacket is it?", "pregunta_es": "¿De quién es la chaqueta?", "opciones": ["The bartender''s.", "The customer''s friend''s.", "The girls''."], "correcta": 1, "explicacion": "It''s my friend''s."}'::jsonb, 'ep7-posesivo-s', 'input', false),
