  ('banco-ep7-adverbios-05', 'banco-ep7', 37, 'libre', '{"pregunta": "Describe how you and your family do things (drive, cook, work, speak) with five adverbs.", "pregunta_es": "Describe cómo hacen las cosas tú y tu familia (manejar, cocinar, trabajar, hablar) con cinco adverbios.", "ejemplo": "I drive carefully. My wife cooks very well. My daughter speaks quickly. We work hard on Saturdays. My father talks loudly.", "criterio": "Adverbios con -ly y los irregulares (well, fast, hard).", "explicacion": "Adverbios con -ly y los irregulares (well, fast, hard)."}'::jsonb, 'ep7-adverbios', 'output', false),
