  ('examen-ep7-adverbios-03', 'examen-ep7', 15, 'escribir', '{"respuestas": ["he arrived late again", "she arrived late again", "he came late again", "she came late again"], "mostrar": "He arrived late again.", "es": "Llegó tarde otra vez.", "explicacion": "late no lleva -ly (lately = últimamente)."}'::jsonb, 'ep7-adverbios', 'estudio', true),
  ('ep7-tag-questions-01', 'ep7-tag-questions', 1, 'elegir', '{"frase": "You''re Colombian, ___?", "opciones": ["are you", "don''t you", "aren''t you"], "correcta": 2, "es": "Eres colombiano, ¿verdad?", "explicacion": "Afirmativa con are → tag negativa: aren''t you?"}'::jsonb, 'ep7-tag-questions', 'estudio', false),
  ('ep7-tag-questions-02', 'ep7-tag-questions', 2, 'elegir', '{"frase": "He can''t drive, ___?", "opciones": ["can he", "does he", "can''t he"], "correcta": 0, "es": "Él no sabe manejar, ¿cierto?", "explicacion": "Negativa → tag afirmativa: can he?"}'::jsonb, 'ep7-tag-questions', 'estudio', false),
  ('ep7-tag-questions-03', 'ep7-tag-questions', 3, 'elegir', '{"frase": "Your sister lives in Spain, ___?", "opciones": ["isn''t she", "doesn''t she", "does she"], "correcta": 1, "es": "Tu hermana vive en España, ¿verdad?", "explicacion": "Presente con -s → doesn''t she?"}'::jsonb, 'ep7-tag-questions', 'estudio', false),
  ('ep7-tag-questions-04', 'ep7-tag-questions', 4, 'elegir', '{"frase": "They went to the party, ___?", "opciones": ["weren''t they", "did they", "didn''t they"], "correcta": 2, "es": "Fueron a la fiesta, ¿cierto?", "explicacion": "Pasado → didn''t they?"}'::jsonb, 'ep7-tag-questions', 'estudio', false),
  ('ep7-tag-questions-05', 'ep7-tag-questions', 5, 'escribir', '{"respuestas": ["you havent seen this film have you", "you have not seen this film have you", "you havent seen this movie have you", "you have not seen this movie have you"], "mostrar": "You haven''t seen this movie, have you?", "es": "No has visto esta película, ¿cierto? (You haven''t…)", "explicacion": "Negativa → tag afirmativa: have you?"}'::jsonb, 'ep7-tag-questions', 'estudio', false),
  ('ep7-tag-questions-06', 'ep7-tag-questions', 6, 'ordenar', '{"frase": "Your shop opens at nine doesn''t it", "es": "Tu tienda abre a las nueve, ¿verdad?", "explicacion": "Afirmativa + tag negativa."}'::jsonb, 'ep7-tag-questions', 'estudio', false),
  ('ep7-tag-questions-07', 'ep7-tag-questions', 7, 'emparejar', '{"pares": [["It''s cold, …", "isn''t it?"], ["You like coffee, …", "don''t you?"], ["She was here, …", "wasn''t she?"], ["We can go, …", "can''t we?"]], "es": "", "explicacion": "El tag repite el auxiliar y cambia el signo."}'::jsonb, 'ep7-tag-questions', 'estudio', false),
  ('ep7-tag-questions-08', 'ep7-tag-questions', 8, 'escuchar', '{"opciones": ["Nobody called, did they?", "Somebody called, did they?", "Nobody called, didn''t they?"], "correcta": 0, "audio": "Nobody called, did they?", "es": "Nadie llamó, ¿cierto?", "explicacion": "nobody es negativo → tag afirmativa; con nobody se usa they."}'::jsonb, 'ep7-tag-questions', 'estudio', false),
  ('banco-ep7-tag-questions-01', 'banco-ep7', 41, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "A: It''s a beautiful day, isn''t it?", "es": "A: Es un día hermoso, ¿verdad?"}, {"en": "B: Yes, it is. You''re going to the beach, aren''t you?", "es": "B: Sí. Vas a ir a la playa, ¿cierto?"}, {"en": "A: No, I''m not. I have to work.", "es": "A: No. Tengo que trabajar."}], "pregunta": "Is A going to the beach?", "pregunta_es": "¿A va a ir a la playa?", "opciones": ["No, A has to work.", "Yes, with B.", "Yes, A is."], "correcta": 0, "explicacion": "No, I''m not. I have to work."}'::jsonb, 'ep7-tag-questions', 'input', false),
  ('banco-ep7-tag-questions-02', 'banco-ep7', 42, 'comprension', '{"modo": "leer", "lineas": [{"en": "Client: These are the new models, aren''t they?", "es": "Clienta: Estos son los modelos nuevos, ¿cierto?"}, {"en": "Uwaldo: Yes, they are. They''re comfortable, aren''t they?", "es": "Uwaldo: Sí. Son cómodos, ¿verdad?"}, {"en": "Client: Very! But they aren''t cheap, are they? — They''re on sale today!", "es": "Clienta: ¡Mucho! Pero no son baratos, ¿cierto? — ¡Hoy están en oferta!"}], "pregunta": "Are the shoes on sale?", "pregunta_es": "¿Los zapatos están en oferta?", "opciones": ["Only tomorrow.", "Yes, today.", "No, they aren''t."], "correcta": 1, "explicacion": "They''re on sale today!"}'::jsonb, 'ep7-tag-questions', 'input', false),
  ('banco-ep7-tag-questions-03', 'banco-ep7', 43, 'decir', '{"es": "Hace calor, ¿verdad?", "respuestas": ["its hot isnt it", "it is hot is not it", "it is hot isnt it"], "mostrar": "It''s hot, isn''t it?", "explicacion": "It''s… → isn''t it?"}'::jsonb, 'ep7-tag-questions', 'output', false),
  ('banco-ep7-tag-questions-04', 'banco-ep7', 44, 'decir', '{"es": "Tú hablas inglés, ¿cierto?", "respuestas": ["you speak english dont you", "you speak english do not you"], "mostrar": "You speak English, don''t you?", "explicacion": "Presente → don''t you?"}'::jsonb, 'ep7-tag-questions', 'output', false),
  ('banco-ep7-tag-questions-05', 'banco-ep7', 45, 'libre', '{"pregunta": "Write four sentences to confirm information about a friend, using tag questions.", "pregunta_es": "Escribe cuatro frases para confirmar información sobre un amigo, usando tag questions.", "ejemplo": "You live in Cúcuta, don''t you? You''re a lawyer, aren''t you? You can''t come on Monday, can you? You went to Bogotá last week, didn''t you?", "criterio": "Afirmativa → tag negativa; negativa → tag afirmativa; mismo auxiliar.", "explicacion": "Afirmativa → tag negativa; negativa → tag afirmativa; mismo auxiliar."}'::jsonb, 'ep7-tag-questions', 'output', false),
