  ('banco-ep7-preguntas-negativas-01', 'banco-ep7', 49, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Wife: Didn''t you buy the bread?", "es": "Esposa: ¿No compraste el pan?"}, {"en": "Husband: No, I didn''t. The bakery wasn''t open.", "es": "Esposo: No. La panadería no estaba abierta."}, {"en": "Wife: Can''t you go to the supermarket, then?", "es": "Esposa: ¿Entonces no puedes ir al supermercado?"}], "pregunta": "Why didn''t he buy the bread?", "pregunta_es": "¿Por qué no compró el pan?", "opciones": ["He forgot.", "He didn''t have money.", "The bakery wasn''t open."], "correcta": 2, "explicacion": "The bakery wasn''t open."}'::jsonb, 'ep7-preguntas-negativas', 'input', false),
  ('banco-ep7-preguntas-negativas-02', 'banco-ep7', 50, 'comprension', '{"modo": "leer", "lineas": [{"en": "Lucas doesn''t like Mondays.", "es": "A Lucas no le gustan los lunes."}, {"en": "He can''t sleep on Sunday nights and he isn''t happy in the morning.", "es": "No puede dormir los domingos en la noche y no está feliz en la mañana."}, {"en": "His friends ask him: \"Don''t you like your job?\" He says: \"I do, but I don''t like waking up early!\"", "es": "Sus amigos le preguntan: \"¿No te gusta tu trabajo?\" Él dice: \"Sí, ¡pero no me gusta madrugar!\""}], "pregunta": "What doesn''t Lucas like?", "pregunta_es": "¿Qué no le gusta a Lucas?", "opciones": ["His friends.", "Waking up early.", "His job."], "correcta": 1, "explicacion": "I don''t like waking up early."}'::jsonb, 'ep7-preguntas-negativas', 'input', false),
