  ('ep8-will-07', 'ep8-will', 7, 'emparejar', '{"pares": [["I''ll", "I will"], ["won''t", "will not"], ["It will rain", "va a llover (predicción)"], ["Will you…?", "¿Puedes…? / ¿Vas a…?"]], "es": "", "explicacion": "will + verbo base, igual para todas las personas."}'::jsonb, 'ep8-will', 'estudio', false),
